mapper.sql:
p.id, p.slug, p.frontend_id, p.frontend_display_id, p.title_en, p.title_zh, p.difficulty, COALESCE(normalized_tags.tag_values_text, '') AS tag_values_text, COALESCE(normalized_tags.tag_labels_en_text, '') AS tag_labels_en_text, COALESCE(normalized_tags.tag_labels_zh_text, '') AS tag_labels_zh_text, p.content_markdown_en, p.content_markdown_zh, p.content_status, p.leetcode_url, p.sample_test_case, p.python3_template, p.source_commit, NULL::TEXT AS recommendation_reason_en, NULL::TEXT AS recommendation_reason_zh, ( SELECT MAX(pcs.frequency_score) FROM problem_company_signal pcs JOIN company c ON c.id = pcs.company_id WHERE pcs.problem_id = p.id
AND c.slug = #{company}
AND pcs.role = #{role}
AND pcs.recency_bucket = #{recencyBucket}
) AS company_frequency_score, ( SELECT COUNT(*) FROM problem_company_signal pcs JOIN company c ON c.id = pcs.company_id WHERE pcs.problem_id = p.id
AND c.slug = #{company}
AND pcs.role = #{role}
AND pcs.recency_bucket = #{recencyBucket}
) AS company_signal_count

where.if:
AND (
  p.title_en ILIKE CONCAT('%', #{keyword}, '%')
  OR p.title_zh ILIKE CONCAT('%', #{keyword}, '%')
  OR p.slug ILIKE CONCAT('%', #{keyword}, '%')
  OR CAST(p.frontend_id AS TEXT) = #{keyword}
  OR p.frontend_display_id = #{keyword}
)

AND EXISTS (
  SELECT 1
  FROM problem_company_signal pcs
  JOIN company c ON c.id = pcs.company_id
  WHERE pcs.problem_id = p.id
    AND c.slug = #{company}

      AND pcs.role = #{role}


      AND pcs.recency_bucket = #{recencyBucket}

)

if.if:
AND EXISTS (
  SELECT 1
  FROM problem_company_signal pcs
  WHERE pcs.problem_id = p.id
    AND pcs.role = #{role}

      AND pcs.recency_bucket = #{recencyBucket}

)

AND EXISTS (
  SELECT 1
  FROM problem_company_signal pcs
  WHERE pcs.problem_id = p.id
    AND pcs.recency_bucket = #{recencyBucket}
)

mapper.update:
UPDATE problem
SET frontend_id = NULL,
    updated_at = NOW()
WHERE frontend_id = #{frontendId}
  AND slug != #{slug}

UPDATE problem
SET frontend_display_id = NULL,
    updated_at = NOW()
WHERE frontend_display_id = #{frontendDisplayId}
  AND slug != #{slug}
